// ===== SMART SCHEDULER =====
// Determines optimal posting times based on data

const staticData = $getWorkflowStaticData('global');
const posts = staticData.posts || [];
const kb = staticData.knowledgeBase || {};

// Analyze historical performance by time
const timePerformance = {};
const dayPerformance = {};

for (const post of posts) {
  if (!post.createdAt || !post.views) continue;

  const date = new Date(post.createdAt);
  const hour = date.getHours();
  const day = date.getDay(); // 0=Sun, 6=Sat

  if (!timePerformance[hour]) timePerformance[hour] = { totalViews: 0, count: 0 };
  timePerformance[hour].totalViews += post.views;
  timePerformance[hour].count++;

  if (!dayPerformance[day]) dayPerformance[day] = { totalViews: 0, count: 0 };
  dayPerformance[day].totalViews += post.views;
  dayPerformance[day].count++;
}

// Calculate average views per time slot
const avgByHour = Object.entries(timePerformance).map(([hour, data]) => ({
  hour: parseInt(hour),
  avgViews: Math.round(data.totalViews / data.count),
  posts: data.count
})).sort((a, b) => b.avgViews - a.avgViews);

const avgByDay = Object.entries(dayPerformance).map(([day, data]) => ({
  day: parseInt(day),
  dayName: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][parseInt(day)],
  avgViews: Math.round(data.totalViews / data.count),
  posts: data.count
})).sort((a, b) => b.avgViews - a.avgViews);

// Best posting times
const bestHours = avgByHour.slice(0, 3).map(h => `${h.hour}:00 (${h.avgViews} avg views)`);
const bestDays = avgByDay.slice(0, 3).map(d => `${d.dayName} (${d.avgViews} avg views)`);

// Determine next optimal post time
const now = new Date();
const currentHour = now.getHours();
const currentDay = now.getDay();

let nextPostTime = null;

// Check if we should post now
const isGoodTime = avgByHour.some(h => h.hour === currentHour && h.avgViews > 500);
const isGoodDay = avgByDay.some(d => d.day === currentDay && d.avgViews > 500);

if (isGoodTime && isGoodDay) {
  nextPostTime = now.toISOString();
} else {
  // Find next best time
  const bestHour = avgByHour[0]?.hour || 12;
  const nextPost = new Date(now);

  if (currentHour >= bestHour) {
    nextPost.setDate(nextPost.getDate() + 1);
  }
  nextPost.setHours(bestHour, 0, 0, 0);
  nextPostTime = nextPost.toISOString();
}

// A/B Test tracking
const abTests = staticData.abTests || [];
const activeTests = abTests.filter(t => t.status === 'active');

// Check A/B test results
const completedTests = [];
for (const test of activeTests) {
  const testPosts = posts.filter(p => p.abTestId === test.id);
  if (testPosts.length >= 2) {
    const winner = testPosts.reduce((best, p) => (p.views || 0) > (best.views || 0) ? p : best);
    test.status = 'completed';
    test.winner = winner.id;
    test.winningHook = winner.hook;
    test.winningViews = winner.views;
    completedTests.push(test);
  }
}

// Generate posting schedule for next 7 days
const schedule = [];
for (let i = 0; i < 7; i++) {
  const date = new Date(now);
  date.setDate(date.getDate() + i);

  const bestHourForDay = avgByHour.find(h => h.hour >= 9)?.hour || 12;
  date.setHours(bestHourForDay, 0, 0, 0);

  schedule.push({
    date: date.toISOString().split('T')[0],
    time: `${bestHourForDay}:00`,
    dayName: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][date.getDay()],
    expectedViews: avgByHour.find(h => h.hour === bestHourForDay)?.avgViews || 'Unknown'
  });
}

return [{
  json: {
    bestHours,
    bestDays,
    nextPostTime,
    schedule,
    completedTests,
    activeTests: activeTests.length,
    chatId: staticData.chatId
  }
}];

// ===== HOOK SPLIT TESTER =====
// Generates multiple hooks for A/B testing

const input = $input.first().json;
const staticData = $getWorkflowStaticData('global');
const kb = staticData.knowledgeBase || {};
const niche = staticData.niche || 'your niche';

// Hook templates based on psychology
const hookTemplates = [
  // Curiosity Gap
  {
    type: 'curiosity_gap',
    templates: [
      `The #1 thing about ${niche} nobody tells you...`,
      `I tried ${niche} for 30 days. Here's what happened...`,
      `Why experts don't want you to know this about ${niche}...`,
      `The secret ${niche} strategy that changed everything...`
    ]
  },
  // Fear of Missing Out
  {
    type: 'fomo',
    templates: [
      `Stop doing ${niche} wrong before it's too late...`,
      `If you're not doing this in ${niche}, you're falling behind...`,
      `99% of people get ${niche} wrong. Are you one of them?`,
      `This ${niche} mistake is costing you everything...`
    ]
  },
  // Social Proof
  {
    type: 'social_proof',
    templates: [
      `How I went from 0 to 100K in ${niche}...`,
      `The ${niche} method that's working for thousands...`,
      `Why top ${niche} creators swear by this...`,
      `The ${niche} trick that got me 1M views...`
    ]
  },
  // Direct Value
  {
    type: 'direct_value',
    templates: [
      `5 ${niche} tips that actually work...`,
      `The ultimate ${niche} guide (save this!)...`,
      `${niche} for beginners: everything you need to know...`,
      `The only ${niche} advice you'll ever need...`
    ]
  },
  // Emotional
  {
    type: 'emotional',
    templates: [
      `I wish I knew this when I started ${niche}...`,
      `The ${niche} truth that no one talks about...`,
      `Why ${niche} is harder than it looks (and what to do)...`,
      `The moment ${niche} finally clicked for me...`
    ]
  }
];

// Generate hooks for next post
const hooksForTesting = hookTemplates.map(template => ({
  type: template.type,
  hook: template.templates[Math.floor(Math.random() * template.templates.length)]
}));

// Create A/B test
const abTest = {
  id: `ab_${Date.now()}`,
  hooks: hooksForTesting,
  status: 'active',
  createdAt: new Date().toISOString(),
  results: []
};

if (!staticData.abTests) staticData.abTests = [];
staticData.abTests.push(abTest);

return [{
  json: {
    ...input,
    abTest,
    hooksForTesting
  }
}];

